    hideGhostCells?: boolean;
}
interface HeatmapCellRectProps {
    cell: {
        column: number;
        row: number;
        x: number;
        y: number;
        width: number;
        height: number;
        color?: string;
        opacity?: number;
    };
    bin: HeatmapBin;
    cornerRadius: number;
    interactive: boolean;
    inactiveOpacity: number;
    inactiveScale: number;
    activeScale: number;
    rowOpacity: number | readonly number[] | undefined;
    hoverState: {
        isHighlighted: boolean;
        isDimmed: boolean;
    };
    onEnter: (column: number, row: number, bin: HeatmapBin, x: number, y: number) => void;
    onLeave: () => void;
}
const HeatmapMotionCell = memo(function HeatmapMotionCell({ cell, bin, cornerRadius, fillScale, interactive, inactiveOpacity, inactiveScale, activeScale, rowOpacity, hoverState, onEnter, onLeave, }: HeatmapCellRectProps & {
    fillScale: (count: number | null | undefined) => string;
}) {
    const { chartStatus, onCellSelect, chartPhase, isLoaded, revealMode, revealEpoch, animationDuration, enterTransition, enterStaggerScale, animateCells, showLoadingCells: showLoadingCellsLayer, loadingCellMaxOpacity, loadingCellRandomness, levelStyles, } = useHeatmap();
    const levelStyle = levelStyles[getHeatmapContributionLevel(bin.count ?? 0)] ?? levelStyles[0];
    const targetFill = fillScale(bin.count);
    const emptyFill = fillScale(0);
    const patternFillOpacity = heatmapLevelCellFillOpacity(levelStyle);
    const dataOpacity = useMotionValue(0);
    /** Orchestration layer: conceal, static loading base. */
    const shimmerOpacity = useMotionValue(0);
    /** Pulse loop only — kept separate so stagger tweens don't break re-entry. */
    const pulseOpacity = useMotionValue(0);
    const wasShimmerPulsingRef = useRef(false);
    const isLoadingResting = chartStatus === "loading" && chartPhase === "loading";
    const isAwaitingLoadingConceal = chartStatus === "loading" && chartPhase === "ready";
    const isExitingToLoading = chartPhase === "exitingReady";
    const isRevealActive = chartPhase === "revealing" &&
        !isLoaded &&
        (revealMode === "fromLoading" || revealMode === "enter");
    const isReadyResting = chartStatus === "ready" && chartPhase === "ready" && isLoaded;
    const participates = useMemo(() => heatmapLoadingCellParticipates(cell.column, cell.row, loadingCellRandomness), [cell.column, cell.row, loadingCellRandomness]);
    const showShimmerPulse = animateCells && showLoadingCellsLayer && participates && isLoadingResting;
    const fadeDurationSec = resolveHeatmapEnterFadeDurationSec(enterTransition, animationDuration);
    const delayMs = computeHeatmapEnterFadeDelayMs({
        column: cell.column,
        row: cell.row,
        revealEpoch,
        animationDurationMs: animationDuration,
        enterStaggerScale,
        fadeDurationSec,
    });
    const staggeredTransition = transitionWithDelay(enterTransition, delayMs / 1000);
    const readyHoverStyle = resolveHeatmapHoverStyle(hoverState.isHighlighted, hoverState.isDimmed, { inactiveOpacity, inactiveScale, activeScale });
