    useEffect(() => {
        if (!showShimmerPulse) {
            wasShimmerPulsingRef.current = false;
            pulseOpacity.set(0);
            return;
        }
        const isFreshLoadingPulse = isLoadingResting && !wasShimmerPulsingRef.current;
        wasShimmerPulsingRef.current = true;
        if (isFreshLoadingPulse) {
            pulseOpacity.set(0);
        }
        let cancelled = false;
        let current: ReturnType<typeof animate> | undefined;
        let pauseTimer: number | undefined;
        let finishPause: (() => void) | undefined;
        const pulse = async () => {
            while (!cancelled) {
