                const duration = 0.35 + Math.random() * 0.85;
                current = animate(pulseOpacity, target, {
                    duration,
                    ease: [0.45, 0, 0.55, 1],
                });
                try {
                    await current;
                }
                catch {
                    break;
                }
                if (cancelled) {
                    break;
                }
                await new Promise<void>((resolve) => {
                    finishPause = resolve;
                    pauseTimer = window.setTimeout(() => {
                        finishPause = undefined;
                        resolve();
                    }, 80 + Math.random() * 420);
                });
            }
        };
        pulse().catch(() => undefined);
        return () => {
            cancelled = true;
            current?.stop();
            if (pauseTimer !== undefined)
                window.clearTimeout(pauseTimer);
            finishPause?.();
        };
    }, [isLoadingResting, loadingCellMaxOpacity, pulseOpacity, showShimmerPulse]);
    useEffect(() => {
        syncHeatmapCellLayerOpacities({
            animateCells,
            chartStatus,
            dataOpacity,
            isAwaitingLoadingConceal,
            isExitingToLoading,
            isLoadingResting,
            isReadyResting,
            isRevealActive,
            participates,
            pulseOpacity,
            readyDataOpacity,
            shimmerOpacity,
            showLoadingCellsLayer,
            showShimmerPulse,
            staggeredTransition,
        });
    }, [
        animateCells,
        chartStatus,
        dataOpacity,
        isAwaitingLoadingConceal,
        isExitingToLoading,
        isLoadingResting,
        isReadyResting,
        isRevealActive,
        participates,
        pulseOpacity,
        readyDataOpacity,
        shimmerOpacity,
        showLoadingCellsLayer,
        showShimmerPulse,
        staggeredTransition,
    ]);
