export const HeatmapCells = memo(function HeatmapCells({ cornerRadius = 2, colorScale: colorScaleProp, inactiveOpacity = HEATMAP_INACTIVE_OPACITY, inactiveScale = 1, activeScale = 1, rowOpacity, interactive = true, hideGhostCells = true, }: HeatmapCellsProps) {
